import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import SiteHeader from "../components/SiteHeader";
import SiteFooter from "../components/SiteFooter";
import { SiteImage } from "../../utils/SiteImage";

const API_BASE = process.env.REACT_APP_API_BASE || "";

// آیکون دسته‌بندی
const CATEGORY_ICONS = {
  "نژادها": "🐕",
  "سلامت": "❤️",
  "آموزش": "📖",
  "عمومی": "🐾",
};

export default function BlogList() {
  const [posts, setPosts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [activeCategory, setActiveCategory] = useState("");
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  useEffect(() => {
    document.title = "بلاگ میکو — مقالات تغذیه سگ";
    window.scrollTo(0, 0);
    fetchCategories();
    fetchPosts();
  }, [activeCategory, search]);

  const fetchPosts = async () => {
    try {
      let url = `${API_BASE}/api/blog?limit=50`;
      if (activeCategory) url += `&category=${encodeURIComponent(activeCategory)}`;
      if (search) url += `&search=${encodeURIComponent(search)}`;
      const res = await fetch(url);
      const data = await res.json();
      setPosts(data.posts || []);
    } catch (err) {
      console.error("Error fetching posts:", err);
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const res = await fetch(`${API_BASE}/api/blog/categories`);
      const data = await res.json();
      setCategories(data.categories || []);
    } catch (err) {
      console.error("Error fetching categories:", err);
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return "";
    const d = new Date(dateStr);
    const months = ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
                    "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"];
    const persianDate = new Intl.DateTimeFormat("fa-IR", {
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(d);
    return persianDate;
  };

  return (
    <>
      <SiteHeader />
      <div className="min-h-screen bg-miko-cream" dir="rtl">
        {/* Hero */}
        <section className="bg-gradient-to-br from-ink-900 via-miko-rust to-miko-pumpkin text-miko-cream pt-32 pb-16 px-6">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block bg-white/10 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm mb-6 border border-white/20">
              بلاگ میکو
            </span>
            <h1 className="text-4xl md:text-6xl font-black mb-6">
              مقالات تغذیه سگ
            </h1>
            <p className="text-lg md:text-xl text-miko-carrot leading-relaxed max-w-2xl mx-auto">
              راهنماهای علمی و کاربردی برای تغذیه سالم سگ شما
            </p>
          </div>
        </section>

        {/* Search & Filters */}
        <section className="py-8 px-6 bg-white border-b border-miko-carrot/20">
          <div className="max-w-5xl mx-auto">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
              <input
                type="text"
                placeholder="جستجو در مقالات..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full md:w-80 px-4 py-3 rounded-xl border border-miko-carrot/30 bg-miko-cream focus:outline-none focus:border-miko-rust focus:ring-2 focus:ring-miko-rust/20 text-miko-dark text-sm"
              />
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={() => setActiveCategory("")}
                  className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                    !activeCategory
                      ? "bg-miko-rust text-white shadow-miko"
                      : "bg-miko-cream text-miko-dark border border-miko-carrot/30 hover:border-miko-rust"
                  }`}
                >
                  همه
                </button>
                {categories.map((cat) => (
                  <button
                    key={cat.name}
                    onClick={() => setActiveCategory(cat.name)}
                    className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-1.5 ${
                      activeCategory === cat.name
                        ? "bg-miko-rust text-white shadow-miko"
                        : "bg-miko-cream text-miko-dark border border-miko-carrot/30 hover:border-miko-rust"
                    }`}
                  >
                    <span>{CATEGORY_ICONS[cat.name] || "📝"}</span>
                    {cat.name}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </section>

        {/* Posts Grid */}
        <section className="py-12 px-6">
          <div className="max-w-5xl mx-auto">
            {loading ? (
              <div className="text-center py-20">
                <div className="inline-block w-12 h-12 border-4 border-miko-carrot/30 border-t-miko-rust rounded-full animate-spin"></div>
                <p className="mt-4 text-miko-dark/60">در حال بارگذاری...</p>
              </div>
            ) : posts.length === 0 ? (
              <div className="text-center py-20">
                <div className="text-5xl mb-4">📭</div>
                <p className="text-miko-dark/60 text-lg">مقاله‌ای یافت نشد</p>
              </div>
            ) : (
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {posts.map((post) => (
                  <Link
                    key={post.id}
                    to={`/blog/${post.slug}`}
                    className="bg-white rounded-2xl border border-miko-carrot/20 overflow-hidden hover:border-miko-rust hover:shadow-lg transition-all group"
                  >
                    {/* Featured Image or Gradient */}
                    {post.featured_image ? (
                      <div className="h-48 overflow-hidden bg-miko-cream">
                        <img
                          src={post.featured_image}
                          alt={post.title}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                        />
                      </div>
                    ) : (
                      <div className="h-48 bg-gradient-to-br from-miko-rust to-miko-pumpkin flex items-center justify-center">
                        <span className="text-5xl">{CATEGORY_ICONS[post.category] || "📝"}</span>
                      </div>
                    )}

                    <div className="p-5">
                      <div className="flex items-center gap-2 mb-3">
                        <span className="text-xs font-bold bg-miko-cream text-miko-rust px-2.5 py-1 rounded-lg border border-miko-carrot/20">
                          {post.category}
                        </span>
                        <span className="text-xs text-miko-dark/50">
                          {formatDate(post.published_at)}
                        </span>
                      </div>

                      <h2 className="text-lg font-bold text-miko-dark mb-2 line-clamp-2 group-hover:text-miko-rust transition-colors">
                        {post.title}
                      </h2>

                      <p className="text-sm text-miko-dark/70 leading-relaxed line-clamp-3">
                        {post.excerpt}
                      </p>

                      <div className="mt-4 flex items-center justify-between">
                        <span className="text-sm font-bold text-miko-rust group-hover:underline">
                          ادامه مطلب ←
                        </span>
                        {post.views_count > 0 && (
                          <span className="text-xs text-miko-dark/40">
                            {post.views_count} بازدید
                          </span>
                        )}
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            )}
          </div>
        </section>
      </div>
      <SiteFooter />
    </>
  );
}
